import 'dart:convert';
import 'package:http/http.dart' as http;
import 'package:shared_preferences/shared_preferences.dart';
class ApiClient{ApiClient._(this.baseUrl,this.cookie);final String baseUrl;final String cookie;static ApiClient? current;static Future<ApiClient> login(String site,String username,String password)async{final base=site.trim().replaceAll(RegExp(r'/+$'),'');final uri=Uri.tryParse(base);if(uri==null||!uri.hasAuthority||!['https','http'].contains(uri.scheme))throw Exception('Enter a valid ERPNext URL.');if(uri.scheme!='https'&&uri.host!='10.0.2.2'&&uri.host!='localhost')throw Exception('Use HTTPS outside local development.');final res=await http.post(Uri.parse(base+'/api/method/login'),headers:{'Content-Type':'application/x-www-form-urlencoded'},body:{'usr':username,'pwd':password}).timeout(const Duration(seconds:20));if(res.statusCode<200||res.statusCode>=300)throw Exception('Sign-in failed. Check credentials and URL.');final raw=res.headers['set-cookie'];if(raw==null||!raw.contains('sid='))throw Exception('No ERPNext session cookie received.');final sid=RegExp(r'sid=([^;]+)').firstMatch(raw)?.group(1);if(sid==null||sid=='Guest')throw Exception('Invalid ERPNext session.');final api=ApiClient._(base,'sid='+sid);current=api;final p=await SharedPreferences.getInstance();await p.setString('employee_hub_site',base);await p.setString('employee_hub_user',username);return api;}Future<dynamic> call(String method,[Map<String,String> args=const{}])async{final res=await http.post(Uri.parse(baseUrl+'/api/method/alienhouse_employee_hub.api.'+method),headers:{'Cookie':cookie,'Content-Type':'application/x-www-form-urlencoded'},body:args).timeout(const Duration(seconds:20));final data=jsonDecode(res.body);if(res.statusCode<200||res.statusCode>=300||data['exc']!=null)throw Exception('ERPNext request failed. Check permissions and configuration.');return data['message'];}}
